package local.cotology.reader;

import org.json.*;
import java.io.*;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;

/** Inert, verified PCM only. Paths and remote URLs are never supplied by a WebView. */
final class AudioStore {
    static final int CHUNK_LIMIT=8*1024*1024, MANIFEST_LIMIT=16*1024*1024;
    static final long QUOTA=8L*1024*1024*1024;
    private final File root;
    static final int MANIFEST_CACHE_BYTES=2*1024*1024,MANIFEST_CACHE_ENTRIES=8;
    private static final class CachedManifest {final JSONObject manifest;final int bytes;CachedManifest(JSONObject manifest,int bytes){this.manifest=manifest;this.bytes=bytes;}}
    // One process-wide budget, including all previously connected servers and profiles.
    private static final LinkedHashMap<String,CachedManifest> manifests=new LinkedHashMap<>(16,0.75f,true);
    private static long cachedManifestBytes=0;
    static long cachedManifestBytes(){synchronized(manifests){return cachedManifestBytes;}}
    static int cachedManifestCount(){synchronized(manifests){return manifests.size();}}
    private static JSONObject cachedManifest(String key){synchronized(manifests){CachedManifest value=manifests.get(key);return value==null?null:value.manifest;}}
    private static void cacheManifest(String key,JSONObject value,int bytes){if(bytes>MANIFEST_CACHE_BYTES)return;synchronized(manifests){CachedManifest previous=manifests.remove(key);if(previous!=null)cachedManifestBytes-=previous.bytes;while(!manifests.isEmpty()&&(manifests.size()>=MANIFEST_CACHE_ENTRIES||cachedManifestBytes+bytes>MANIFEST_CACHE_BYTES)){Iterator<CachedManifest> oldest=manifests.values().iterator();cachedManifestBytes-=oldest.next().bytes;oldest.remove();}manifests.put(key,new CachedManifest(value,bytes));cachedManifestBytes+=bytes;}}
    AudioStore(File root) throws IOException {this.root=root;directory(root);}
    static String id(String value) throws IOException {if(value==null||!value.matches("[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}"))throw new IOException("Неверный идентификатор аудио");return value;}
    static String hash(byte[] bytes) throws Exception {byte[] digest=MessageDigest.getInstance("SHA-256").digest(bytes);StringBuilder s=new StringBuilder();for(byte b:digest)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
    static String checksum(String value) throws IOException {if(value==null||!value.matches("[a-f0-9]{64}"))throw new IOException("Не указан SHA-256 аудио");return value;}
    static long integer(JSONObject value,String key,long min,long max) throws Exception {Object raw=value.get(key);if(!(raw instanceof Number))throw new IOException("Неверное число "+key);double n=((Number)raw).doubleValue();long result=((Number)raw).longValue();if(!Double.isFinite(n)||n!=result||result<min||result>max)throw new IOException("Неверное число "+key);return result;}
    static double number(JSONObject value,String key) throws Exception {Object raw=value.get(key);if(!(raw instanceof Number)||!Double.isFinite(((Number)raw).doubleValue()))throw new IOException("Неверное число "+key);return ((Number)raw).doubleValue();}
    private static void exact(JSONObject value,String... keys) throws Exception {java.util.Set<String> allowed=new java.util.HashSet<>(java.util.Arrays.asList(keys));if(value.length()!=keys.length)throw new IOException("Посторонние поля аудио");java.util.Iterator<String> it=value.keys();while(it.hasNext())if(!allowed.contains(it.next()))throw new IOException("Посторонние поля аудио");}
    static void directory(File dir) throws IOException {if(Files.isSymbolicLink(dir.toPath()))throw new IOException("Ссылка вместо каталога");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("Не удалось создать каталог аудио");}
    private File profile(String profile) throws IOException {File f=new File(root,id(profile));directory(f);return f;}
    private File job(String profile,String job) throws IOException {File f=new File(profile(profile),id(job));directory(f);return f;}
    static byte[] read(File f,int max) throws IOException {if(Files.isSymbolicLink(f.toPath())||!f.isFile()||f.length()>max)throw new IOException("Файл аудио отсутствует или повреждён");try(InputStream in=new FileInputStream(f);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[16384];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>max)throw new IOException("Файл слишком большой");out.write(buffer,0,n);}return out.toByteArray();}}
    static void atomic(File file,byte[] bytes) throws IOException {directory(file.getParentFile());if(Files.isSymbolicLink(file.toPath()))throw new IOException("Ссылка вместо файла");File temporary=new File(file.getParentFile(),".write-"+UUID.randomUUID()+".tmp");try{try(FileOutputStream out=new FileOutputStream(temporary)){out.write(bytes);out.getFD().sync();}Files.move(temporary.toPath(),file.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}finally{Files.deleteIfExists(temporary.toPath());}}
    static JSONObject validateManifest(byte[] raw,String expectedJob) throws Exception {
        if(raw.length<2||raw.length>MANIFEST_LIMIT)throw new IOException("Неверный размер манифеста");String decoded=StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).onUnmappableCharacter(java.nio.charset.CodingErrorAction.REPORT).decode(ByteBuffer.wrap(raw)).toString();JSONObject m=new JSONObject(decoded);
        exact(m,"schemaVersion","jobId","kind","sourceSha256","recipeSha256","quality","workId","expressionId","editionId","segments");
        if(integer(m,"schemaVersion",1,1)!=1||!id(m.getString("jobId")).equals(id(expectedJob))||!m.getString("kind").equals("audio")||!m.getString("quality").equals("technical-unlistened"))throw new IOException("Неверный манифест аудио");
        checksum(m.getString("sourceSha256"));checksum(m.getString("recipeSha256"));id(m.getString("workId"));id(m.getString("expressionId"));id(m.getString("editionId"));
        JSONArray parts=m.getJSONArray("segments");if(parts.length()<1||parts.length()>50000)throw new IOException("Неверное количество фрагментов");long total=0;
        for(int i=0;i<parts.length();i++){JSONObject s=parts.getJSONObject(i);exact(s,"ordinal","sha256","bytes","mediaType","durationSeconds","sampleRate","url");long size=integer(s,"bytes",46,CHUNK_LIMIT);double duration=number(s,"durationSeconds"),frames=duration*22050;if(integer(s,"ordinal",0,49999)!=i||duration<0.1||duration>180||Math.abs(frames-Math.round(frames))>0.00001||Math.round(frames)*2+44!=size||integer(s,"sampleRate",22050,22050)!=22050||!s.getString("mediaType").equals("audio/wav")||!s.getString("url").equals(segmentPath(expectedJob,i)))throw new IOException("Неверный фрагмент аудио");checksum(s.getString("sha256"));total+=size;}
        return m;
    }
    static String segmentPath(String job,int ordinal) throws IOException {id(job);if(ordinal<0||ordinal>49999)throw new IOException("Неверный фрагмент");return "/api/derived/jobs/"+job+"/audio/segments/"+ordinal;}
    static double validateWave(byte[] bytes,JSONObject segment) throws Exception {
        if(bytes.length!=segment.getInt("bytes")||bytes.length>CHUNK_LIMIT||bytes.length<46||!hash(bytes).equals(segment.getString("sha256")))throw new IOException("Аудио не совпадает с SHA-256");
        ByteBuffer b=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);if(b.getInt(0)!=0x46464952||b.getInt(8)!=0x45564157||Integer.toUnsignedLong(b.getInt(4))+8!=bytes.length)throw new IOException("Неверный WAV");
        int offset=12,data=-1,dataLength=0;boolean format=false;
        while(offset+8<=bytes.length){int tag=b.getInt(offset);long length=Integer.toUnsignedLong(b.getInt(offset+4));long end=(long)offset+8+length;if(end>bytes.length)throw new IOException("Оборванный WAV");int start=offset+8;
            if(tag==0x20746d66){if(format||length!=16||b.getShort(start)!=1||b.getShort(start+2)!=1||b.getInt(start+4)!=22050||b.getInt(start+8)!=44100||b.getShort(start+12)!=2||b.getShort(start+14)!=16)throw new IOException("Неподдерживаемый PCM");format=true;}
            else if(tag==0x61746164){if(data!=-1)throw new IOException("Повторный PCM");data=start;dataLength=(int)length;}
            else throw new IOException("Постороннее содержимое WAV");offset=(int)(end+(length&1));
        }
        double duration=dataLength/44100.0;if(offset!=bytes.length||!format||data<0||dataLength%2!=0||duration<0.1||duration>180||Math.abs(duration-segment.getDouble("durationSeconds"))>1.0/22050)throw new IOException("Неверная длительность PCM");
        int nonzero=0,clipped=0;for(int i=data;i<data+dataLength;i+=2){int sample=b.getShort(i);if(sample!=0)nonzero++;if(Math.abs(sample)>=32760)clipped++;}if(nonzero==0||(double)clipped/(dataLength/2)>0.02)throw new IOException("Тишина или повреждённый PCM");return duration;
    }
    synchronized JSONObject register(String profile,String job,byte[] raw,String expectedHash,String title,String author) throws Exception {
        JSONObject manifest=validateManifest(raw,job);String sha=hash(raw);if(expectedHash!=null&&!sha.equals(checksum(expectedHash)))throw new IOException("Манифест не совпадает с SHA-256 сервера");JSONObject old=get(profile,job);
        if(old!=null){if(!sha.equals(old.getString("manifestSha256")))throw new IOException("Версия аудиокниги изменилась");if(!clean(title,300).trim().isEmpty())old.put("title",clean(title,300));if(!clean(author,300).trim().isEmpty())old.put("author",clean(author,300));save(old);return old;}
        long total=0;JSONArray parts=manifest.getJSONArray("segments");for(int i=0;i<parts.length();i++)total+=parts.getJSONObject(i).getLong("bytes");
        double duration=0;for(int i=0;i<parts.length();i++)duration+=parts.getJSONObject(i).getDouble("durationSeconds");
        JSONObject row=new JSONObject().put("profileId",id(profile)).put("jobId",id(job)).put("manifestSha256",sha).put("manifest",manifest).put("title",clean(title,300)).put("author",clean(author,300)).put("status","registered").put("downloadedSegments",0).put("totalSegments",parts.length()).put("totalBytes",total).put("totalDurationSeconds",duration).put("downloadedBytes",0).put("error",JSONObject.NULL).put("updatedAt",System.currentTimeMillis());
        atomic(new File(job(profile,job),"manifest.json"),raw);save(row);return row;
    }
    private static String clean(String value,int max){if(value==null)return "";return value.substring(0,Math.min(max,value.length())).replaceAll("[\\x00-\\x1f\\x7f]", " ");}
    private void save(JSONObject row) throws Exception {row.put("updatedAt",System.currentTimeMillis());JSONObject metadata=new JSONObject();Iterator<String> keys=row.keys();while(keys.hasNext()){String key=keys.next();if(!key.equals("manifest"))metadata.put(key,row.get(key));}atomic(new File(job(row.getString("profileId"),row.getString("jobId")),"record.json"),metadata.toString().getBytes(StandardCharsets.UTF_8));}
    private JSONObject metadata(String profile,String job) throws Exception {File parent=new File(root,id(profile));if(Files.isSymbolicLink(parent.toPath()))throw new IOException("Ссылка в хранилище");File dir=new File(parent,id(job));if(Files.isSymbolicLink(dir.toPath()))throw new IOException("Ссылка в хранилище");File f=new File(dir,"record.json");if(!f.exists())return null;JSONObject row=new JSONObject(new String(read(f,65536),StandardCharsets.UTF_8));if(!row.getString("profileId").equals(profile)||!row.getString("jobId").equals(job))throw new IOException("Неверная локальная запись");checksum(row.getString("manifestSha256"));integer(row,"totalSegments",1,50000);integer(row,"downloadedSegments",0,row.getInt("totalSegments"));integer(row,"totalBytes",46,50000L*CHUNK_LIMIT);integer(row,"downloadedBytes",0,row.getLong("totalBytes"));if(!java.util.Arrays.asList("registered","downloading","partial","complete","error").contains(row.getString("status")))throw new IOException("Неверное состояние аудио");return row;}
    synchronized JSONObject get(String profile,String job) throws Exception {JSONObject row=metadata(profile,job);if(row==null)return null;String key=root.getAbsolutePath()+":"+profile+":"+job+":"+row.getString("manifestSha256");JSONObject manifest=cachedManifest(key);if(manifest==null){byte[] raw=read(new File(job(profile,job),"manifest.json"),MANIFEST_LIMIT);if(!hash(raw).equals(row.getString("manifestSha256")))throw new IOException("Манифест повреждён");manifest=validateManifest(raw,job);cacheManifest(key,manifest,raw.length);}row.put("manifest",manifest);return row;}
    synchronized JSONArray list(String profile) throws Exception {JSONArray out=new JSONArray();File[] jobs=profile(profile).listFiles();if(jobs!=null)for(File f:jobs)if(f.isDirectory()&&!Files.isSymbolicLink(f.toPath()))try{JSONObject row=metadata(profile,f.getName());if(row!=null)out.put(row);}catch(Exception ignored){}return out;}
    synchronized void recoverInterrupted(String profile,String job) throws Exception {JSONObject row=metadata(profile,job);if(row!=null&&row.getString("status").equals("downloading")){row.put("status","partial").put("error",JSONObject.NULL);save(row);}}
    synchronized JSONObject status(String profile,String job,String status,String error) throws Exception {JSONObject row=require(profile,job);row.put("status",status).put("error",error==null?JSONObject.NULL:clean(error,300));save(row);return row;}
    synchronized JSONObject require(String profile,String job) throws Exception {JSONObject row=get(profile,job);if(row==null)throw new IOException("Аудиокнига не добавлена");return row;}
    static long size(File file) throws IOException {if(Files.isSymbolicLink(file.toPath()))throw new IOException("Ссылка в хранилище");if(file.isFile())return file.length();long total=0;File[] children=file.listFiles();if(children!=null)for(File f:children)total+=size(f);return total;}
    synchronized JSONObject putChunk(String profile,String job,int ordinal,byte[] bytes) throws Exception {JSONObject row=require(profile,job);JSONObject segment=row.getJSONObject("manifest").getJSONArray("segments").getJSONObject(ordinal);validateWave(bytes,segment);File file=chunkFile(profile,job,ordinal);if(root.getUsableSpace()<bytes.length+256L*1024*1024)throw new IOException("Недостаточно места для аудио (лимит 8 ГБ)");atomic(file,bytes);return row;}
    File chunkFile(String profile,String job,int ordinal) throws Exception {if(ordinal<0||ordinal>49999)throw new IOException("Неверный фрагмент");return new File(job(profile,job),String.format(Locale.ROOT,"%05d.wav",ordinal));}
    synchronized byte[] chunk(String profile,String job,int ordinal) throws Exception {JSONObject row=require(profile,job);JSONObject segment=row.getJSONObject("manifest").getJSONArray("segments").getJSONObject(ordinal);byte[] bytes=read(chunkFile(profile,job,ordinal),CHUNK_LIMIT);validateWave(bytes,segment);return bytes;}
    synchronized JSONObject recount(String profile,String job,String status,String error) throws Exception {JSONObject row=require(profile,job);JSONArray parts=row.getJSONObject("manifest").getJSONArray("segments");int count=0;long bytes=0;for(int i=0;i<parts.length();i++){try{byte[] content=read(chunkFile(profile,job,i),CHUNK_LIMIT);validateWave(content,parts.getJSONObject(i));count++;bytes+=content.length;}catch(IOException ignored){}}
        row.put("downloadedSegments",count).put("downloadedBytes",bytes).put("status",count==parts.length()?"complete":status).put("error",error==null?JSONObject.NULL:clean(error,300));save(row);return row;}
    synchronized JSONObject markDownloaded(String profile,String job,int count,long bytes) throws Exception {JSONObject row=require(profile,job);row.put("downloadedSegments",count).put("downloadedBytes",bytes).put("status",count==row.getInt("totalSegments")?"complete":"downloading").put("error",JSONObject.NULL);save(row);return row;}
    synchronized Object positionGet(String profile,String job) throws Exception {JSONObject row=require(profile,job);File f=new File(job(profile,job),"position.json");if(!f.exists())return JSONObject.NULL;try{JSONObject p=new JSONObject(new String(read(f,8192),StandardCharsets.UTF_8));return validatePosition(row,p);}catch(Exception invalid){return JSONObject.NULL;}}
    private static JSONObject validatePosition(JSONObject row,JSONObject p) throws Exception {
        int ordinal=(int)integer(p,"ordinal",0,49999);double seconds=number(p,"seconds"),rate=p.has("rate")?number(p,"rate"):1;long updatedAt=integer(p,"updatedAt",0,9007199254740991L);JSONArray parts=row.getJSONObject("manifest").getJSONArray("segments");
        if(!p.getString("jobId").equals(row.getString("jobId"))||!p.getString("manifestSha256").equals(row.getString("manifestSha256"))||ordinal>=parts.length()||seconds<0||seconds>parts.getJSONObject(ordinal).getDouble("durationSeconds")+1.0/22050||rate<0.5||rate>2||!(p.get("completed") instanceof Boolean))throw new IOException("Неверная позиция аудио");
        seconds=Math.min(seconds,parts.getJSONObject(ordinal).getDouble("durationSeconds"));while(ordinal<parts.length()-1&&seconds>=parts.getJSONObject(ordinal).getDouble("durationSeconds")){seconds-=parts.getJSONObject(ordinal).getDouble("durationSeconds");ordinal++;}
        return new JSONObject().put("jobId",row.getString("jobId")).put("ordinal",ordinal).put("seconds",seconds).put("rate",rate).put("manifestSha256",p.getString("manifestSha256")).put("updatedAt",updatedAt).put("completed",ordinal==parts.length()-1&&seconds>=parts.getJSONObject(ordinal).getDouble("durationSeconds"));
    }
    synchronized JSONObject positionPut(String profile,String job,JSONObject p) throws Exception {JSONObject value=validatePosition(require(profile,job),p);Object previous=positionGet(profile,job);if(previous instanceof JSONObject&&((JSONObject)previous).getLong("updatedAt")>value.getLong("updatedAt"))return (JSONObject)previous;value.put("updatedAt",System.currentTimeMillis());atomic(new File(job(profile,job),"position.json"),value.toString().getBytes(StandardCharsets.UTF_8));return value;}
    synchronized boolean remove(String profile,String job) throws Exception {delete(job(profile,job));return true;}
    private static void delete(File f) throws IOException {if(Files.isSymbolicLink(f.toPath()))throw new IOException("Ссылка в хранилище");File[] children=f.listFiles();if(children!=null)for(File child:children)delete(child);Files.deleteIfExists(f.toPath());}
}
